import static org.junit.Assert.assertEquals;

public class LookupTranslator_translate_TriageGen2Test {

    @Test
    public void testTranslate_MatchLongest_Greedy() throws IOException {
        // Setup: "ab" -> "1", "abc" -> "2"
        // Greedy should pick "abc" if available
        LookupTranslator translator = new LookupTranslator(
            new CharSequence[]{"ab", "1"},
            new CharSequence[]{"abc", "2"}
        );

        StringWriter out = new StringWriter();
        String input = "abcde";

        // Test greedy match (starts at 0, looks for longest first)
        int result = translator.translate(input, 0, out);

        assertEquals(3, result);
        assertEquals("2", out.toString());
    }














}

